1	/**
2	 * Shared-hosting account provisioner (Phase 1).
3	 *
4	 * ┌────────────────────────────────────────────────────────────────────────┐
5	 * │ SAFETY POSTURE — READ BEFORE ENABLING                                    │
6	 * │                                                                          │
7	 * │ This provisions UNTRUSTED customers side-by-side on ONE box. The         │
8	 * │ isolation shell (jailed user + per-user PHP-FPM pool + open_basedir +    │
9	 * │ disk quota + scoped DB + chrooted SFTP) is the standard Hestia/cPanel    │
10	 * │ model, but multi-tenant isolation is the one place a subtle gap is a     │
11	 * │ CROSS-CUSTOMER BREACH. So the whole provisioner is INERT unless          │
12	 * │ `ENABLE_SHARED_HOSTING=1` AND not SANDBOX. Do NOT flip that flag in      │
13	 * │ production until this has been (1) reviewed as a security change,        │
14	 * │ (2) validated end-to-end on a dedicated STAGING shared node,             │
15	 * │ (3) paired with fail2ban + ModSecurity + a malware scanner.             │
16	 * │                                                                          │
17	 * │ The sshd change (SFTP chroot) is `sshd -t`-validated BEFORE any reload,  │
18	 * │ so a bad config can never lock the box out — but it still deserves the   │
19	 * │ staging pass.                                                            │
20	 * └────────────────────────────────────────────────────────────────────────┘
21	 *
22	 * Everything a shell touches is validated through the tested pure helpers in
23	 * lib/hosting.ts BEFORE interpolation.
24	 */
25	
26	import { Client } from "ssh2";
27	import { randomBytes } from "node:crypto";
28	import { promises as dns } from "node:dns";
29	import { db } from "../lib/db";
30	import { SANDBOX } from "../lib/sandbox";
31	import { decryptSecret, encryptSecret } from "../lib/crypto-box";
32	import {
33	  isValidUnixUsername,
34	  isValidHostingDomain,
35	  planLimits,
36	  diskQuotaBlocks,
37	  accountPaths,
38	  accountFsPlan,
39	  fpmPoolConfig,
40	  buildScopedGrantSql,
41	} from "../lib/hosting";
42	
43	/** Shell-escape the raw SQL from buildScopedGrantSql for embedding in a
44	 *  double-quoted `mysql -e "..."`. Identifiers/passwords are already validated
45	 *  to safe charsets; only the SQL's own backticks need escaping so the shell
46	 *  doesn't treat them as command substitution. */
47	function sqlForMysqlExec(sql: string): string {
48	  return sql.replace(/`/g, "\\`");
49	}
50	
51	const ENABLED = process.env.ENABLE_SHARED_HOSTING === "1";
52	const CONNECT_TIMEOUT_MS = 20_000;
53	const STEP_TIMEOUT_MS = 60_000;
54	
55	/** Alphanumeric password (shell/SQL-safe: no quoting hazards). */
56	function strongPassword(len = 22): string {
57	  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
58	  const bytes = randomBytes(len);
59	  let out = "";
60	  for (let i = 0; i < len; i++) out += alphabet[bytes[i] % alphabet.length];
61	  return out;
62	}
63	
64	async function connectNode(node: { sshHost: string; sshPort: number; rootPasswordEnc: string | null }): Promise<Client> {
65	  const password = node.rootPasswordEnc ? decryptSecret(node.rootPasswordEnc) : "";
66	  if (!password) throw new Error("Hosting node has no root credential on record.");
67	  const conn = new Client();
68	  await new Promise<void>((resolve, reject) => {
69	    const timer = setTimeout(() => { try { conn.end(); } catch { /* */ } reject(new Error("SSH connect timed out")); }, CONNECT_TIMEOUT_MS);
70	    conn
71	      .on("ready", () => { clearTimeout(timer); resolve(); })
72	      .on("error", (e) => { clearTimeout(timer); reject(e); })
73	      .connect({ host: node.sshHost, port: node.sshPort, username: "root", password, readyTimeout: CONNECT_TIMEOUT_MS });
74	  });
75	  return conn;
76	}
77	
78	function exec(conn: Client, command: string, timeoutMs = STEP_TIMEOUT_MS): Promise<{ code: number; out: string }> {
79	  return new Promise((resolve, reject) => {
80	    const timer = setTimeout(() => reject(new Error("command timed out")), timeoutMs);
81	    conn.exec(command, (err, stream) => {
82	      if (err) { clearTimeout(timer); return reject(err); }
83	      let out = "";
84	      stream
85	        .on("close", (code: number) => { clearTimeout(timer); resolve({ code: code ?? 0, out }); })
86	        .on("data", (d: Buffer) => { out += d.toString(); })
87	        .stderr.on("data", (d: Buffer) => { out += d.toString(); });
88	    });
89	  });
90	}
91	
92	async function run(conn: Client, label: string, cmd: string): Promise<void> {
93	  const r = await exec(conn, cmd, STEP_TIMEOUT_MS);
94	  if (r.code !== 0) throw new Error(`${label} failed: ${r.out.slice(0, 300)}`);
95	}
96	
97	/**
98	 * The name-based nginx vhost for one account — HTTP-only until a cert exists, and
99	 * HTTP→HTTPS + a 443 SNI block once it does. Shared IP; routed purely by
100	 * server_name; PHP proxied to THIS account's socket only, root jailed to its
101	 * webroot. Pure string — no interpolation reaches a shell here.
102	 */
103	function renderHostingVhost(username: string, domain: string, webroot: string, sock: string, sslLiveDir: string | null): string {
104	  const phpLoc = [
105	    `    location ~ \\.php$ {`,
106	    `        include fastcgi_params;`,
107	    `        fastcgi_pass unix:${sock};`,
108	    `        fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;`,
109	    `    }`,
110	  ].join("\n");
111	  const body = [
112	    `    root ${webroot};`,
113	    `    index index.php index.html;`,
114	    `    location / { try_files $uri $uri/ /index.php?$query_string; }`,
115	    phpLoc,
116	    `    location ~ /\\. { deny all; }`,
117	  ].join("\n");
118	  const http = [
119	    `server {`,
120	    `    listen 80;`,
121	    `    listen [::]:80;`,
122	    `    server_name ${domain} www.${domain};`,
123	    `    location ^~ /.well-known/acme-challenge/ { root /var/www/html; }`,
124	    sslLiveDir ? `    location / { return 301 https://$host$request_uri; }` : body,
125	    `}`,
126	  ].join("\n");
127	  if (!sslLiveDir) return http + "\n";
128	  const https = [
129	    `server {`,
130	    `    listen 443 ssl;`,
131	    `    listen [::]:443 ssl;`,
132	    `    server_name ${domain} www.${domain};`,
133	    `    ssl_certificate ${sslLiveDir}/fullchain.pem;`,
134	    `    ssl_certificate_key ${sslLiveDir}/privkey.pem;`,
135	    `    ssl_protocols TLSv1.2 TLSv1.3;`,
136	    body,
137	    `}`,
138	  ].join("\n");
139	  return `${http}\n${https}\n`;
140	}
141	
142	/** Write a vhost file + enable it, tested before reload. */
143	async function installVhost(conn: Client, username: string, conf: string): Promise<void> {
144	  const path = `/etc/nginx/sites-available/hosting-${username}.conf`;
145	  await run(conn, "write vhost", `cat > ${path} <<'VH'\n${conf}VH\nln -sfn ${path} /etc/nginx/sites-enabled/hosting-${username}.conf`);
146	  await run(conn, "test + reload nginx", `nginx -t && systemctl reload nginx`);
147	}
148	
149	/** Write + (re)load an account's FPM pool for a given PHP version. The pool
150	 *  contents (the PHP isolation boundary) come from the tested pure generator in
151	 *  lib/hosting.ts — socket path is unchanged across versions so the vhost never
152	 *  needs editing when PHP is switched. */
153	async function writeFpmPool(conn: Client, u: string, home: string, webroot: string, php: string): Promise<void> {
154	  if (!/^\d\.\d$/.test(php)) throw new Error(`refusing unsafe php version ${php}`);
155	  await run(conn, "php-fpm pool", `cat > /etc/php/${php}/fpm/pool.d/${u}.conf <<'POOL'\n${fpmPoolConfig(u, home, webroot)}\nPOOL\nsystemctl reload php${php}-fpm 2>/dev/null || systemctl restart php${php}-fpm`);
156	}
157	
158	/**
159	 * The isolation shell for one account (HTTP-only vhost; SSL added later by the
160	 * sweep once DNS points at us). Every interpolated value has already cleared a
161	 * validator, so nothing here can be a shell metacharacter.
162	 */
163	async function applyIsolation(
164	  conn: Client,
165	  a: { username: string; primaryDomain: string; diskQuotaMB: number; sftpPassword: string },
166	  php: string,
167	): Promise<void> {
168	  const u = a.username;
169	  const d = a.primaryDomain;
170	  if (!isValidUnixUsername(u)) throw new Error(`refusing unsafe username ${u}`);
171	  if (!isValidHostingDomain(d)) throw new Error(`refusing unsafe domain ${d}`);
172	  if (!/^\d\.\d$/.test(php)) throw new Error(`refusing unsafe php version ${php}`);
173	  const { home, webroot } = accountPaths(u);
174	  const hardBlocks = diskQuotaBlocks(Math.max(1, Math.round(a.diskQuotaMB / 1024)));
175	  const softBlocks = Math.floor(hardBlocks * 0.95);
176	  const sock = `/run/php/${u}.sock`;
177	
178	  // 1. Jailed user. Home is ROOT-owned (a chroot requirement); the user owns only
179	  //    public_html + tmp under it. nologin shell — SFTP-only via the chroot below.
180	  //
181	  // Perms come from the tested accountFsPlan(): home 711 (chroot-safe + nginx can
182	  // TRAVERSE to the webroot but a peer tenant can't LIST the home), webroot
183	  // 2750 <user>:www-data (nginx reads via the www-data GROUP, never world — the
184	  // old world-readable 755 let any tenant read a neighbour's wp-config.php if
185	  // open_basedir was escaped; the setgid bit keeps tenant-created files in the
186	  // www-data group so nginx keeps serving them), tmp 700 (private PHP scratch).
187	  const fs = accountFsPlan(u);
188	  await run(conn, "create user", `id -u ${u} >/dev/null 2>&1 || useradd -m -d ${home} -s /usr/sbin/nologin ${u}`);
189	  await run(
190	    conn,
191	    "chroot-safe home",
192	    `mkdir -p ${webroot} ${home}/tmp && ` +
193	      `chown ${fs.home.owner} ${home} && chmod ${fs.home.mode} ${home} && ` +
194	      `chown ${fs.webroot.owner} ${webroot} && chmod ${fs.webroot.mode} ${webroot} && ` +
195	      `chown ${fs.tmp.owner} ${home}/tmp && chmod ${fs.tmp.mode} ${home}/tmp`,
196	  );
197	  await run(conn, "sftp password", `printf '%s:%s' ${u} '${a.sftpPassword}' | chpasswd`);
198	
199	  // 2. Disk quota (fs must have usrquota — node onboarding enables it).
200	  await run(conn, "disk quota", `command -v setquota >/dev/null 2>&1 && setquota -u ${u} ${softBlocks} ${hardBlocks} 0 0 /home || echo 'quota tool absent — skipped'`);
201	
202	  // 3. Per-user PHP-FPM pool — THE PHP isolation boundary.
203	  await writeFpmPool(conn, u, home, webroot, php);
204	
205	  // 4. Name-based vhost (HTTP only for now).
206	  await installVhost(conn, u, renderHostingVhost(u, d, webroot, sock, null));
207	
208	  // 5. Chrooted SFTP — sshd -t GUARDED so a bad config can never lock out the box.
209	  const sftpConf = [
210	    `Match User ${u}`,
211	    `    ChrootDirectory ${home}`,
212	    `    ForceCommand internal-sftp`,
213	    `    AllowTcpForwarding no`,
214	    `    X11Forwarding no`,
215	  ].join("\n");
216	  const sshdFile = `/etc/ssh/sshd_config.d/nxeon-${u}.conf`;
217	  await run(
218	    conn,
219	    "sftp chroot (guarded)",
220	    // Write to a temp include, validate the WHOLE sshd config, and only then move
221	    // it into place + reload. If sshd -t fails, discard — never reload a broken config.
222	    `mkdir -p /etc/ssh/sshd_config.d && cat > ${sshdFile}.new <<'SSHD'\n${sftpConf}\nSSHD\n` +
223	      `cp -f ${sshdFile}.new ${sshdFile} && if sshd -t 2>/dev/null; then systemctl reload ssh 2>/dev/null || systemctl reload sshd; else rm -f ${sshdFile}; echo 'sshd -t rejected the chroot block — SFTP not enabled, box untouched'; fi; rm -f ${sshdFile}.new`,
224	  );
225	}
226	
227	// ---- DB provisioning (per-account, on demand) ------------------------------
228	
229	/** Create ONE scoped MySQL/MariaDB user+db on the account's node. */
230	async function provisionHostingDatabase(dbId: string): Promise<void> {
231	  const rec = await db.hostingDatabase.findUnique({ where: { id: dbId }, include: { account: { include: { node: true } } } });
232	  if (!rec || rec.status !== "PENDING") return;
233	  if (SANDBOX || !ENABLED) {
234	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: SANDBOX ? "ACTIVE" : "PENDING", passwordEnc: null, error: SANDBOX ? null : "Shared hosting not enabled." } });
235	    return;
236	  }
237	  const name = rec.name;
238	  const user = rec.dbUser;
239	  const pass = rec.passwordEnc ? decryptSecret(rec.passwordEnc) : "";
240	  // DB name + user were built from the validated username; re-assert shape.
241	  if (!/^[a-z0-9_]{1,64}$/.test(name) || !/^[a-z0-9_]{1,32}$/.test(user) || !pass) {
242	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: "FAILED", error: "invalid db identifiers" } });
243	    return;
244	  }
245	  try {
246	    const conn = await connectNode(rec.account.node);
247	    try {
248	      // Grants scoped to THIS database only — the data-isolation boundary.
249	      // buildScopedGrantSql escapes _/% so the GRANT can't bleed onto a peer's db.
250	      const sql = sqlForMysqlExec(buildScopedGrantSql(name, user, pass));
251	      await run(conn, "create database", `mysql -e "${sql}"`);
252	    } finally {
253	      try { conn.end(); } catch { /* */ }
254	    }
255	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: "ACTIVE", passwordEnc: null, error: null } });
256	  } catch (e) {
257	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: "FAILED", error: (e instanceof Error ? e.message : String(e)).slice(0, 300) } });
258	  }
259	}
260	
261	export async function hostingDatabaseSweep(): Promise<void> {
262	  const pending = await db.hostingDatabase.findMany({ where: { status: "PENDING" }, select: { id: true }, take: 10 });
263	  for (const p of pending) await provisionHostingDatabase(p.id).catch((e) => console.error(`[hosting] db ${p.id} failed`, e));
264	}
265	
266	// ---- Account provisioning --------------------------------------------------
267	
268	export async function provisionHostingAccount(accountId: string): Promise<void> {
269	  const account = await db.hostingAccount.findUnique({ where: { id: accountId }, include: { node: true, plan: true } });
270	  if (!account || account.status !== "PENDING") return;
271	  await db.hostingAccount.update({ where: { id: account.id }, data: { status: "PROVISIONING", error: null } });
272	
273	  if (SANDBOX || !ENABLED) {
274	    if (SANDBOX) {
275	      const pw = strongPassword();
276	      await db.hostingAccount.update({ where: { id: account.id }, data: { status: "ACTIVE", provisionedAt: new Date(), sftpPasswordEnc: encryptSecret(pw), error: null } });
277	    } else {
278	      await db.hostingAccount.update({ where: { id: account.id }, data: { status: "PENDING", error: "Shared hosting is not enabled on this deployment yet." } });
279	    }
280	    return;
281	  }
282	
283	  try {
284	    const allowed = planLimits(account.plan).phpVersions;
285	    const php = allowed.includes(account.phpVersion) ? account.phpVersion : allowed[0];
286	    const sftpPassword = strongPassword();
287	    const conn = await connectNode(account.node);
288	    try {
289	      await applyIsolation(conn, { username: account.username, primaryDomain: account.primaryDomain, diskQuotaMB: account.diskQuotaMB, sftpPassword }, php);
290	    } finally {
291	      try { conn.end(); } catch { /* */ }
292	    }
293	    await db.hostingAccount.update({ where: { id: account.id }, data: { status: "ACTIVE", provisionedAt: new Date(), sftpPasswordEnc: encryptSecret(sftpPassword), error: null } });
294	  } catch (e) {
295	    await db.hostingAccount.update({ where: { id: account.id }, data: { status: "FAILED", error: (e instanceof Error ? e.message : String(e)).slice(0, 300) } });
296	  }
297	}
298	
299	export async function hostingProvisionSweep(): Promise<void> {
300	  const pending = await db.hostingAccount.findMany({ where: { status: "PENDING" }, select: { id: true }, take: 10 });
301	  for (const p of pending) await provisionHostingAccount(p.id).catch((e) => console.error(`[hosting] provision ${p.id} failed`, e));
302	}
303	
304	// ---- SSL sweep (post-DNS, no sshd risk) ------------------------------------
305	
306	/** True once `domain` resolves (A) to the node's shared IP — DNS is pointed at us. */
307	async function domainPointsAt(domain: string, ip: string): Promise<boolean> {
308	  try {
309	    const a = await dns.resolve4(domain);
310	    return a.includes(ip);
311	  } catch {
312	    return false;
313	  }
314	}
315	
316	/**
317	 * For each ACTIVE account without HTTPS, once its domain resolves to the node's
318	 * shared IP, issue a per-domain cert (webroot) and upgrade the vhost to a 443 SNI
319	 * block. Safe: touches only nginx + certbot, never sshd.
320	 */
321	export async function hostingSslSweep(): Promise<void> {
322	  if (SANDBOX || !ENABLED) return;
323	  const accts = await db.hostingAccount.findMany({
324	    where: { status: "ACTIVE", sslActive: false },
325	    include: { node: true },
326	    take: 20,
327	  });
328	  for (const a of accts) {
329	    try {
330	      if (!isValidHostingDomain(a.primaryDomain) || !isValidUnixUsername(a.username)) continue;
331	      if (!(await domainPointsAt(a.primaryDomain, a.node.publicIp))) continue; // DNS not pointed yet
332	      const d = a.primaryDomain;
333	      const conn = await connectNode(a.node);
334	      try {
335	        const issue = await exec(conn, `certbot certonly --webroot -w /var/www/html -d ${d} -d www.${d} --non-interactive --agree-tos --register-unsafely-without-email --keep-until-expiring 2>&1`, 3 * 60_000);
336	        const liveDir = `/etc/letsencrypt/live/${d}`;
337	        const have = await exec(conn, `test -s ${liveDir}/fullchain.pem && echo yes || echo no`);
338	        if (have.out.trim() !== "yes") { console.log(`[hosting] cert for ${d} not issued yet: ${issue.out.slice(0, 160)}`); continue; }
339	        const { webroot } = accountPaths(a.username);
340	        await installVhost(conn, a.username, renderHostingVhost(a.username, d, webroot, `/run/php/${a.username}.sock`, liveDir));
341	      } finally {
342	        try { conn.end(); } catch { /* */ }
343	      }
344	      await db.hostingAccount.update({ where: { id: a.id }, data: { sslActive: true } });
345	      console.log(`[hosting] HTTPS active for ${a.primaryDomain}`);
346	    } catch (e) {
347	      console.error(`[hosting] ssl sweep ${a.id} failed`, e);
348	    }
349	  }
350	}
351	
352	// ---- Panel task queue (PHP switch, WordPress, backup, restore) -------------
353	
354	const SAFE_ID = /^[a-z0-9_]{1,64}$/;
355	const SAFE_EMAIL = /^[A-Za-z0-9._%+-]{1,64}@[A-Za-z0-9.-]{1,190}\.[A-Za-z]{2,24}$/;
356	
357	async function failTask(id: string, msg: string): Promise<void> {
358	  await db.hostingTask.update({ where: { id }, data: { status: "FAILED", error: msg } }).catch(() => undefined);
359	}
360	
361	/** Move an account's FPM pool to a new PHP version (socket path is unchanged, so
362	 *  the vhost never needs editing). */
363	async function taskPhpSwitch(conn: Client, a: { id: string; username: string; phpVersion: string }, payload: string | null): Promise<void> {
364	  const version = String(JSON.parse(payload || "{}").version ?? "");
365	  if (!/^\d\.\d$/.test(version)) throw new Error("invalid php version");
366	  const { home, webroot } = accountPaths(a.username);
367	  if (version !== a.phpVersion) {
368	    await run(conn, "remove old pool", `rm -f /etc/php/${a.phpVersion}/fpm/pool.d/${a.username}.conf; systemctl reload php${a.phpVersion}-fpm 2>/dev/null || true`);
369	  }
370	  await writeFpmPool(conn, a.username, home, webroot, version);
371	  await db.hostingAccount.update({ where: { id: a.id }, data: { phpVersion: version } });
372	}
373	
374	/** One-click WordPress: create the DB, drop WordPress in the webroot, install it
375	 *  as the jailed account user via WP-CLI. Returns the admin login (shown once). */
376	/** Re-check the plan DB cap at DB-creation time. The worker processes tasks
377	 *  SEQUENTIALLY, so this is the serialization point that closes the TOCTOU race
378	 *  the action-level gate can't (audit 2026-08-01). */
379	async function assertDbCap(accountId: string, maxDatabases: number): Promise<void> {
380	  const n = await db.hostingDatabase.count({ where: { accountId, status: { in: ["PENDING", "ACTIVE"] } } });
381	  if (n >= maxDatabases) throw new Error("Your plan's database limit is reached.");
382	}
383	
384	async function taskWordpressInstall(conn: Client, a: { id: string; username: string; primaryDomain: string; maxDatabases: number }, payload: string | null): Promise<string> {
385	  await assertDbCap(a.id, a.maxDatabases);
386	  const p = JSON.parse(payload || "{}") as { dbName?: string; dbUser?: string; dbPassEnc?: string; adminUser?: string; adminPassEnc?: string; adminEmail?: string };
387	  const dbName = String(p.dbName ?? "");
388	  const dbUser = String(p.dbUser ?? "");
389	  const dbPass = (p.dbPassEnc ? decryptSecret(p.dbPassEnc) : "") ?? "";
390	  const adminUser = String(p.adminUser ?? "");
391	  const adminPass = (p.adminPassEnc ? decryptSecret(p.adminPassEnc) : "") ?? "";
392	  const adminEmail = String(p.adminEmail ?? "");
393	  if (!SAFE_ID.test(dbName) || !SAFE_ID.test(dbUser.slice(0, 32)) || !dbPass) throw new Error("invalid db identifiers");
394	  if (!/^[A-Za-z0-9_]{1,32}$/.test(adminUser) || !/^[A-Za-z0-9]{8,64}$/.test(adminPass) || !SAFE_EMAIL.test(adminEmail)) throw new Error("invalid admin identifiers");
395	  const u = a.username;
396	  const d = a.primaryDomain;
397	  if (!isValidUnixUsername(u) || !isValidHostingDomain(d)) throw new Error("unsafe account");
398	  const { webroot } = accountPaths(u);
399	
400	  await run(conn, "wp-cli", `command -v wp >/dev/null 2>&1 || (curl -fsSL https://raw.githubusercontent.com/wp-cli/builds/gh-pages/phar/wp-cli.phar -o /usr/local/bin/wp && chmod +x /usr/local/bin/wp)`);
401	  const sql = sqlForMysqlExec(buildScopedGrantSql(dbName, dbUser, dbPass));
402	  await run(conn, "wp db", `mysql -e "${sql}"`);
403	  const wp = `sudo -u ${u} -H wp --path=${webroot}`;
404	  await run(conn, "wp download", `${wp} core download --force`);
405	  await run(conn, "wp config", `${wp} config create --dbname=${dbName} --dbuser=${dbUser} --dbpass='${dbPass}' --force`);
406	  await run(conn, "wp install", `${wp} core install --url='https://${d}' --title='${d}' --admin_user='${adminUser}' --admin_password='${adminPass}' --admin_email='${adminEmail}' --skip-email`);
407	  await db.hostingDatabase.create({ data: { accountId: a.id, name: dbName, dbUser, passwordEnc: null, status: "ACTIVE" } }).catch(() => undefined);
408	  // Shown ONCE in the panel, then the task result is cleared.
409	  return JSON.stringify({ adminUser, adminPassword: adminPass, url: `https://${d}/wp-admin/` });
410	}
411	
412	/**
413	 * One-click app catalog (beyond WordPress). Each recipe downloads the app into
