432	async function taskAppInstall(conn: Client, a: { id: string; username: string; primaryDomain: string; maxDatabases: number }, payload: string | null): Promise<string> {
433	  const p = JSON.parse(payload || "{}") as { slug?: string; dbName?: string; dbUser?: string; dbPassEnc?: string };
434	  const slug = String(p.slug ?? "");
435	  const recipe = APP_RECIPES[slug];
436	  if (!recipe) throw new Error("unknown app");
437	  if (recipe.needsDb) await assertDbCap(a.id, a.maxDatabases);
438	  const u = a.username;
439	  if (!isValidUnixUsername(u)) throw new Error("unsafe account");
440	  const { webroot } = accountPaths(u);
441	  const isBz2 = recipe.url.endsWith(".bz2");
442	  const tarFlags = `${isBz2 ? "xjf" : "xzf"} - ${recipe.strip ? `--strip-components=${recipe.strip}` : ""}`;
443	  // Download + extract into the webroot AS the account user (jailed).
444	  await run(conn, `download ${slug}`, `sudo -u ${u} -H bash -c "cd ${webroot} && curl -fsSL '${recipe.url}' | tar ${tarFlags}"`);
445	  let dbInfo = "";
446	  if (recipe.needsDb) {
447	    const dbName = String(p.dbName ?? "");
448	    const dbUser = String(p.dbUser ?? "");
449	    const dbPass = (p.dbPassEnc ? decryptSecret(p.dbPassEnc) : "") ?? "";
450	    if (!/^[a-z0-9_]{1,64}$/.test(dbName) || !/^[a-z0-9_]{1,32}$/.test(dbUser) || !dbPass) throw new Error("invalid db identifiers");
451	    const sql = sqlForMysqlExec(buildScopedGrantSql(dbName, dbUser, dbPass));
452	    await run(conn, "app db", `mysql -e "${sql}"`);
453	    await db.hostingDatabase.create({ data: { accountId: a.id, name: dbName, dbUser, passwordEnc: null, status: "ACTIVE" } }).catch(() => undefined);
454	    dbInfo = ` Database: ${dbName} · user ${dbUser} · password ${dbPass} (host localhost).`;
455	  }
456	  return JSON.stringify({ app: recipe.name, url: `https://${a.primaryDomain}/`, note: recipe.note + dbInfo });
457	}
