459	/** Archive the account's home + DB dumps to a node-local backups dir.
460	 *
461	 * SECURITY (audit 2026-08-01, cross-tenant DB compromise): the DB dumps are
462	 * written to a ROOT-ONLY directory OUTSIDE the tenant's chroot and are NEVER
463	 * chowned to the tenant. The old code dumped into ${home}/.dbdump and chowned it
464	 * to the account user, so the tenant — who holds live SFTP creds chrooted to
465	 * ${home} — could race in and overwrite <db>.sql with arbitrary SQL that restore
466	 * later piped into `mysql` as root (a shared-node-wide GRANT/USE). Keeping the
467	 * dumps root-owned and off the tenant tree means the archived SQL is always our
468	 * own mysqldump output, never tenant-controlled. */
469	async function taskBackup(conn: Client, a: { id: string; username: string }, tsLabel: string): Promise<void> {
470	  const u = a.username;
471	  const dir = `/var/hosting-backups/${u}`;
472	  const dumpDir = `${dir}/dbdump`;
473	  const path = `${dir}/${tsLabel}.tar.gz`;
474	  // Root-only staging for the DB dumps; the whole dir is 700 root:root so the
475	  // tenant can neither read nor tamper with it.
476	  await run(
477	    conn,
478	    "dump dbs",
479	    `rm -rf ${dumpDir}; mkdir -p ${dumpDir}; chown -R root:root ${dir}; chmod 700 ${dir} ${dumpDir}; ` +
480	      `for dbn in $(mysql -N -e "SHOW DATABASES LIKE '${u}\\_%'" 2>/dev/null); do mysqldump "$dbn" > ${dumpDir}/"$dbn".sql 2>/dev/null; done`,
481	  );
482	  // One archive holding the home tree (${u}/…) and the root-owned dumps (dbdump/…).
483	  await run(conn, "tar home", `tar -czf ${path} -C /home ${u} -C ${dir} dbdump && rm -rf ${dumpDir}`);
484	  const st = await exec(conn, `stat -c %s ${path} 2>/dev/null || echo 0`);
485	  const sizeBytes = Math.max(0, Math.min(2_000_000_000, Number(st.out.trim()) || 0));
486	  await db.hostingBackup.create({ data: { accountId: a.id, path, sizeBytes } });
487	  // Retain the newest 5 per account; delete older files + rows.
488	  const all = await db.hostingBackup.findMany({ where: { accountId: a.id }, orderBy: { createdAt: "desc" } });
489	  for (const old of all.slice(5)) {
490	    await exec(conn, `rm -f ${old.path}`).catch(() => undefined);
491	    await db.hostingBackup.delete({ where: { id: old.id } }).catch(() => undefined);
492	  }
493	}
