495	/** Restore a backup over the account (destructive: overwrites files + DBs).
496	 *
497	 * The archive is extracted to a ROOT-ONLY staging dir (never straight into the
498	 * tenant's writable tree), and only DB dumps in THIS tenant's namespace
499	 * (`${u}_*.sql`) are replayed — so a restore can never touch another tenant's
500	 * database, and the SQL content is our own dump, not anything the tenant could
501	 * have planted (see taskBackup). */
502	async function taskRestore(conn: Client, a: { id: string; username: string }, payload: string | null): Promise<void> {
503	  const backupId = String(JSON.parse(payload || "{}").backupId ?? "");
504	  const b = await db.hostingBackup.findFirst({ where: { id: backupId, accountId: a.id } });
505	  if (!b) throw new Error("backup not found");
506	  const u = a.username;
507	  const { home, webroot } = accountPaths(u);
508	  if (!/^\/var\/hosting-backups\/[a-z0-9]+\/[A-Za-z0-9._-]+\.tar\.gz$/.test(b.path)) throw new Error("unsafe backup path");
509	  const stage = `/var/hosting-backups/${u}/.restore`;
510	  await run(conn, "extract", `rm -rf ${stage}; mkdir -p ${stage}; chown root:root ${stage}; chmod 700 ${stage}; tar -xzf ${b.path} -C ${stage}`);
511	  // Files: the archive root holds ${u}/… — copy it back over the home.
512	  await run(conn, "restore files", `[ -d ${stage}/${u} ] && cp -a ${stage}/${u}/. ${home}/ 2>/dev/null; true`);
513	  // DBs: replay ONLY dumps named for this tenant's own databases (${u}_*). The
514	  // shell `case` guard is belt-and-braces on top of the glob — a dump for
515	  // another tenant's DB is never fed to mysql.
516	  await run(
517	    conn,
518	    "restore dbs",
519	    `for f in ${stage}/dbdump/${u}_*.sql; do [ -f "$f" ] || continue; bn=$(basename "$f" .sql); ` +
520	      `case "$bn" in ${u}_*) mysql "$bn" < "$f" 2>/dev/null;; esac; done`,
521	  );
522	  // Re-assert the hardened perms the restored tree may have flattened: webroot
523	  // stays <user>:www-data setgid (nginx reads via group, peers don't), tmp private.
524	  const rfs = accountFsPlan(u);
525	  await run(
526	    conn,
527	    "fix perms",
528	    `chown -R ${rfs.webroot.owner} ${webroot} 2>/dev/null; chmod ${rfs.webroot.mode} ${webroot} 2>/dev/null; ` +
529	      `chown -R ${rfs.tmp.owner} ${home}/tmp 2>/dev/null; chmod ${rfs.tmp.mode} ${home}/tmp 2>/dev/null; rm -rf ${stage}; true`,
530	  );
531	}
