533	async function processHostingTask(taskId: string): Promise<void> {
534	  const task = await db.hostingTask.findUnique({ where: { id: taskId }, include: { account: { include: { node: true } } } });
535	  if (!task || task.status !== "PENDING") return;
536	  await db.hostingTask.update({ where: { id: task.id }, data: { status: "RUNNING" } });
537	  const a = task.account;
538	  if (a.status !== "ACTIVE") { await failTask(task.id, "the account is not active"); return; }
539	  try {
540	    const conn = await connectNode(a.node);
541	    try {
542	      let result: string | null = null;
543	      if (task.kind === "PHP_SWITCH") await taskPhpSwitch(conn, a, task.payload);
544	      else if (task.kind === "WORDPRESS_INSTALL") result = await taskWordpressInstall(conn, a, task.payload);
545	      else if (task.kind === "APP_INSTALL") result = await taskAppInstall(conn, a, task.payload);
546	      else if (task.kind === "BACKUP") await taskBackup(conn, a, task.id);
547	      else if (task.kind === "RESTORE") await taskRestore(conn, a, task.payload);
548	      await db.hostingTask.update({ where: { id: task.id }, data: { status: "DONE", result, error: null } });
549	    } finally { try { conn.end(); } catch { /* */ } }
550	  } catch (e) {
551	    await failTask(task.id, (e instanceof Error ? e.message : String(e)).slice(0, 300));
552	  }
553	}
