555	export async function hostingTaskSweep(): Promise<void> {
556	  if (SANDBOX) {
557	    const pend = await db.hostingTask.findMany({ where: { status: "PENDING" }, select: { id: true, kind: true, account: { select: { primaryDomain: true } } }, take: 10 });
558	    for (const t of pend) {
559	      const result = t.kind === "WORDPRESS_INSTALL" ? JSON.stringify({ adminUser: "admin", adminPassword: "sandbox-demo-pw", url: `https://${t.account.primaryDomain}/wp-admin/` })
560	        : t.kind === "APP_INSTALL" ? JSON.stringify({ app: "App", url: `https://${t.account.primaryDomain}/`, note: "Sandbox: finish the installer in your browser." }) : null;
561	      await db.hostingTask.update({ where: { id: t.id }, data: { status: "DONE", result } });
562	      if (t.kind === "BACKUP") await db.hostingBackup.create({ data: { accountId: (await db.hostingTask.findUnique({ where: { id: t.id }, select: { accountId: true } }))!.accountId, path: `/var/hosting-backups/sandbox/${t.id}.tar.gz`, sizeBytes: 12_345_678 } }).catch(() => undefined);
563	    }
564	    return;
565	  }
566	  if (!ENABLED) return;
567	  const pend = await db.hostingTask.findMany({ where: { status: "PENDING" }, select: { id: true }, take: 5 });
568	  for (const t of pend) await processHostingTask(t.id).catch((e) => console.error(`[hosting] task ${t.id} failed`, e));
569	}
