380	/** Take an account OFFLINE without destroying data: drop the nginx site, remove
381	 *  the FPM pool (no PHP), and lock the unix user (no SFTP/login). Reversible. */
382	async function taskSuspend(conn: Client, a: LifecycleAccount): Promise<void> {
383	  if (!isValidUnixUsername(a.username)) throw new Error("unsafe account username");
384	  await run(conn, "suspend: disable vhost", `rm -f /etc/nginx/sites-enabled/hosting-${a.username}.conf; nginx -t && systemctl reload nginx || true`);
385	  await run(conn, "suspend: remove fpm pool", `rm -f /etc/php/${a.phpVersion}/fpm/pool.d/${a.username}.conf; systemctl reload php${a.phpVersion}-fpm 2>/dev/null || true`);
386	  await run(conn, "suspend: lock user", `usermod -L ${a.username} 2>/dev/null || true; pkill -u ${a.username} 2>/dev/null || true`);
