390	async function taskUnsuspend(conn: Client, a: LifecycleAccount): Promise<void> {
391	  if (!isValidUnixUsername(a.username)) throw new Error("unsafe account username");
392	  const { home, webroot } = accountPaths(a.username);
393	  await writeFpmPool(conn, a.username, home, webroot, a.phpVersion);
394	  await run(conn, "unsuspend: enable vhost", `ln -sfn /etc/nginx/sites-available/hosting-${a.username}.conf /etc/nginx/sites-enabled/hosting-${a.username}.conf; nginx -t && systemctl reload nginx || true`);
395	  await run(conn, "unsuspend: unlock user", `usermod -U ${a.username} 2>/dev/null || true`);
