493	/** Archive the account's home + DB dumps to a node-local backups dir.
494	 *
495	 * SECURITY (audit 2026-08-01, cross-tenant DB compromise): the DB dumps are
496	 * written to a ROOT-ONLY directory OUTSIDE the tenant's chroot and are NEVER
497	 * chowned to the tenant. The old code dumped into ${home}/.dbdump and chowned it
498	 * to the account user, so the tenant — who holds live SFTP creds chrooted to
499	 * ${home} — could race in and overwrite <db>.sql with arbitrary SQL that restore
500	 * later piped into `mysql` as root (a shared-node-wide GRANT/USE). Keeping the
501	 * dumps root-owned and off the tenant tree means the archived SQL is always our
502	 * own mysqldump output, never tenant-controlled. */
503	async function taskBackup(conn: Client, a: { id: string; username: string }, tsLabel: string): Promise<void> {
504	  const u = a.username;
505	  const dir = `/var/hosting-backups/${u}`;
506	  const dumpDir = `${dir}/dbdump`;
507	  const path = `${dir}/${tsLabel}.tar.gz`;
508	  // Root-only staging for the DB dumps; the whole dir is 700 root:root so the
509	  // tenant can neither read nor tamper with it.
510	  await run(
511	    conn,
512	    "dump dbs",
513	    `rm -rf ${dumpDir}; mkdir -p ${dumpDir}; chown -R root:root ${dir}; chmod 700 ${dir} ${dumpDir}; ` +
514	      `for dbn in $(mysql -N -e "SHOW DATABASES LIKE '${u}\\_%'" 2>/dev/null); do mysqldump "$dbn" > ${dumpDir}/"$dbn".sql 2>/dev/null; done`,
515	  );
516	  // One archive holding the home tree (${u}/…) and the root-owned dumps (dbdump/…).
517	  await run(conn, "tar home", `tar -czf ${path} -C /home ${u} -C ${dir} dbdump && rm -rf ${dumpDir}`);
518	  const st = await exec(conn, `stat -c %s ${path} 2>/dev/null || echo 0`);
519	  const sizeBytes = Math.max(0, Math.min(2_000_000_000, Number(st.out.trim()) || 0));
520	  await db.hostingBackup.create({ data: { accountId: a.id, path, sizeBytes } });
521	  // Retain the newest 5 per account; delete older files + rows.
522	  const all = await db.hostingBackup.findMany({ where: { accountId: a.id }, orderBy: { createdAt: "desc" } });
523	  for (const old of all.slice(5)) {
524	    await exec(conn, `rm -f ${old.path}`).catch(() => undefined);
525	    await db.hostingBackup.delete({ where: { id: old.id } }).catch(() => undefined);
526	  }
527	}
