531	 * The archive is extracted to a ROOT-ONLY staging dir (never straight into the
532	 * tenant's writable tree), and only DB dumps in THIS tenant's namespace
533	 * (`${u}_*.sql`) are replayed — so a restore can never touch another tenant's
534	 * database, and the SQL content is our own dump, not anything the tenant could
535	 * have planted (see taskBackup). */
536	async function taskRestore(conn: Client, a: { id: string; username: string }, payload: string | null): Promise<void> {
537	  const backupId = String(JSON.parse(payload || "{}").backupId ?? "");
538	  const b = await db.hostingBackup.findFirst({ where: { id: backupId, accountId: a.id } });
539	  if (!b) throw new Error("backup not found");
540	  const u = a.username;
541	  const { home, webroot } = accountPaths(u);
542	  if (!/^\/var\/hosting-backups\/[a-z0-9]+\/[A-Za-z0-9._-]+\.tar\.gz$/.test(b.path)) throw new Error("unsafe backup path");
543	  const stage = `/var/hosting-backups/${u}/.restore`;
544	  await run(conn, "extract", `rm -rf ${stage}; mkdir -p ${stage}; chown root:root ${stage}; chmod 700 ${stage}; tar -xzf ${b.path} -C ${stage}`);
545	  // Files: the archive root holds ${u}/… — copy it back over the home.
546	  await run(conn, "restore files", `[ -d ${stage}/${u} ] && cp -a ${stage}/${u}/. ${home}/ 2>/dev/null; true`);
547	  // DBs: replay ONLY dumps named for this tenant's own databases (${u}_*). The
548	  // shell `case` guard is belt-and-braces on top of the glob — a dump for
549	  // another tenant's DB is never fed to mysql.
550	  await run(
551	    conn,
552	    "restore dbs",
553	    `for f in ${stage}/dbdump/${u}_*.sql; do [ -f "$f" ] || continue; bn=$(basename "$f" .sql); ` +
554	      `case "$bn" in ${u}_*) mysql "$bn" < "$f" 2>/dev/null;; esac; done`,
555	  );
556	  // Re-assert the hardened perms the restored tree may have flattened: webroot
557	  // stays <user>:www-data setgid (nginx reads via group, peers don't), tmp private.
558	  const rfs = accountFsPlan(u);
559	  await run(
560	    conn,
561	    "fix perms",
562	    `chown -R ${rfs.webroot.owner} ${webroot} 2>/dev/null; chmod ${rfs.webroot.mode} ${webroot} 2>/dev/null; ` +
563	      `chown -R ${rfs.tmp.owner} ${home}/tmp 2>/dev/null; chmod ${rfs.tmp.mode} ${home}/tmp 2>/dev/null; rm -rf ${stage}; true`,
564	  );
565	}
