567	async function processHostingTask(taskId: string): Promise<void> {
568	  const task = await db.hostingTask.findUnique({ where: { id: taskId }, include: { account: { include: { node: true } } } });
569	  if (!task || task.status !== "PENDING") return;
570	  await db.hostingTask.update({ where: { id: task.id }, data: { status: "RUNNING" } });
571	  const a = task.account;
572	  if (a.status !== "ACTIVE") { await failTask(task.id, "the account is not active"); return; }
573	  try {
574	    const conn = await connectNode(a.node);
575	    try {
576	      let result: string | null = null;
577	      if (task.kind === "PHP_SWITCH") await taskPhpSwitch(conn, a, task.payload);
578	      else if (task.kind === "WORDPRESS_INSTALL") result = await taskWordpressInstall(conn, a, task.payload);
579	      else if (task.kind === "APP_INSTALL") result = await taskAppInstall(conn, a, task.payload);
580	      else if (task.kind === "BACKUP") await taskBackup(conn, a, task.id);
581	      else if (task.kind === "RESTORE") await taskRestore(conn, a, task.payload);
582	      else if (task.kind === "SUSPEND") await taskSuspend(conn, a);
583	      else if (task.kind === "UNSUSPEND") await taskUnsuspend(conn, a);
584	      else if (task.kind === "TERMINATE") await taskTerminate(conn, a);
585	      await db.hostingTask.update({ where: { id: task.id }, data: { status: "DONE", result, error: null } });
586	    } finally { try { conn.end(); } catch { /* */ } }
587	  } catch (e) {
588	    await failTask(task.id, (e instanceof Error ? e.message : String(e)).slice(0, 300));
589	  }
590	}
