/**
 * Server-side page guard. Redirects to /login if signed out, or back to the
 * overview if the (staff) user's role can't reach this area. Returns the real
 * signed-in user (impersonation is refused elsewhere in the admin layout).
 */
export async function requireArea(area: Area): Promise<User> {
  const user = await realUser();
  if (!user) redirect("/login");
  if (!isStaff(user.role)) redirect("/dashboard");
  if (!canAccess(user.role, area)) redirect("/admin");
  return user;
}
=== HostingTaskKind enum ===
enum HostingTaskKind {
  PHP_SWITCH
  WORDPRESS_INSTALL
  APP_INSTALL
  BACKUP
  RESTORE
  // Account lifecycle — enacted by the provisioner (inert until ENABLE_SHARED_HOSTING).
  SUSPEND // disable vhost + FPM pool + lock the unix user (reversible)
  UNSUSPEND // reverse a SUSPEND
  TERMINATE // remove vhost/FPM, delete the jailed user + home, drop scoped DBs
}

enum HostingTaskStatus {
  PENDING
  RUNNING
  DONE
  FAILED
}

/// A queued panel operation on an account, run by the worker over the node SSH
/// (PHP switch, one-click app install, backup, restore). `payload`/`result` hold
/// small JSON; any secret in a result (e.g. a WordPress admin password) is
/// shown ONCE then cleared.
model HostingTask {
  id        String            @id @default(cuid())
  accountId String
  account   HostingAccount    @relation(fields: [accountId], references: [id], onDelete: Cascade)
  kind      HostingTaskKind
  status    HostingTaskStatus @default(PENDING)
  payload   String? // JSON in
  result    String? // JSON out (may hold a one-time secret until read)
  error     String?
  createdAt DateTime          @default(now())
  updatedAt DateTime          @updatedAt

  @@index([status])
  @@index([accountId])
}

/// A stored backup of an account (home archive + DB dumps) on its node.
model HostingBackup {
  id        String         @id @default(cuid())
